setupTeam();assert.equal(run('fighters[0].hp'),120);assert.equal(run('teamState(fighters[0]).members.map(m=>m.hp).join()'),'40,40,40');assert.equal(run('getMoves(fighters[0]).map(m=>m[0]).join()'),'Sprint,Energy Drink,Switch');assert.equal(run('new Set(ATHLETES.map(a=>a.skin)).size'),3);run('attack(0,1)');assert.equal(run('fighters[0].hp'),115);assert.equal(run('teamState(fighters[0]).members[0].hp'),35);assert.equal(run('heroSpeed(fighters[0])'),337.5);step(.25);run('attack(0,0)');step(.35);assert.equal(run('fighters[1].hp'),113);run('attack(0,2)');assert.equal(run('teamState(fighters[0]).active'),1);assert.equal(run('getMoves(fighters[0])[0][0]'),'Splash');const runnerCD=run('teamState(fighters[0]).members[0].cd[0]');assert(runnerCD>3);run('attack(0,2)');assert.equal(run('teamState(fighters[0]).active'),1);run('switchAthlete(fighters[0]);switchAthlete(fighters[0])');assert.equal(run('teamState(fighters[0]).members[0].hp'),35);assert.equal(run('fighters[0].cd[0]'),runnerCD);
setupTeam();run('teamState(fighters[0]).members[0].hp=5;syncTeam(fighters[0]);attack(0,1)');assert.equal(run('teamState(fighters[0]).members[0].hp'),5);assert.equal(run('fighters[0].cd[1]'),0);
setupTeam();run('applyDamage(fighters[0],1000)');assert.equal(run('fighters[0].hp'),80);assert.equal(run('teamState(fighters[0]).active'),1);run('applyDamage(fighters[0],1000)');assert.equal(run('fighters[0].hp'),40);assert.equal(run('teamState(fighters[0]).active'),2);run('applyDamage(fighters[0],1000)');assert.equal(run('fighters[0].hp'),0);step(.01);assert.equal(run('roundOver'),true);run('if(cardDraft)selectAbilityCard("skip");spawnRound();useTestMap()');assert.equal(run('fighters[0].hp'),120);assert.equal(run('teamState(fighters[0]).members.every(m=>m.hp===40)'),true);
setupTeam();run('switchAthlete(fighters[0]);attack(0,0)');step(.8);assert.equal(run('fighters[1].hp'),128);assert(run('fighters[1].x>300'));run('fighters[0].anim=0;attack(0,1);hit(fighters[1],fighters[0],20)');assert.equal(run('fighters[0].hp'),120);assert(run('fighters[0].dodge>0'));
setupTeam();run("switchAthlete(fighters[0]);mapId='harbor';walls=MAPS.harbor.walls;fighters[0].x=600;fighters[0].y=350");assert.equal(run('terrainSpeed(fighters[0])'),1);assert.equal(run('heroSpeed(fighters[0])'),320);
setupTeam();run('switchAthlete(fighters[0]);switchAthlete(fighters[0]);attack(0,0)');step(.4);assert.equal(run('fighters[1].hp'),137);assert.equal(run('fighters[1].athletics.bleed'),1);
setupTeam();run('switchAthlete(fighters[0]);switchAthlete(fighters[0]);attack(0,1)');step(.25);assert(run('zones.some(z=>z.kind==="ice")'));assert.equal(run('terrainAt(fighters[0]).ice'),true);assert.equal(run('heroSpeed(fighters[0])'),360);run('attack(0,0)');step(.3);assert.equal(run('fighters[1].athletics.bleed'),3);assert.equal(run('fighters[1].hp'),137);
setupTeam();run('addBleed(fighters[1],5)');step(1.01);assert.equal(run('fighters[1].hp'),139);step(2);assert.equal(run('fighters[1].hp'),137);assert.equal(run('fighters[1].athletics.bleed'),5);run('spawnRound();useTestMap()');assert.equal(run('fighters[1].athletics.bleed'),0);assert.equal(run('zones.length'),0);
setupTeam();run("loadouts[0]=['vitality'];spawnRound();useTestMap();applyDamage(fighters[0],10);healFighter(fighters[0],5);render()");assert.equal(run('fighters[0].maxHp'),155);assert(Math.abs(run('fighters[0].hp')-150)<.001);assert.equal(run('validAthletics(fighters[0])'),true);
console.log('PASS: Olympic Team female skin-tone variants, 3x40 HP, two moves plus Switch, personal HP/cooldown retention, energy cost/buff, auto death switch/final defeat/reset, Splash/Dive/water speed, strong ice dash/trails, permanent stacking Bleed and card/healing integration.');
setupTeam();run("switchAthlete(fighters[0]);keys.add('w');attack(0,1)");assert.equal(run('fighters[0].dy'),-1);step(.1);const diveX=run('fighters[0].x'),diveY=run('fighters[0].y'),diveClock=run('mapClock');run("keys.clear();keys.add('d')");step(.1);assert(Math.abs(run('fighters[0].x')-diveX-450*(run('mapClock')-diveClock))<.001);assert(Math.abs(run('fighters[0].y')-diveY)<.001);run('keys.clear()');const coastX=run('fighters[0].x'),coastClock=run('mapClock');step(.05);assert(Math.abs(run('fighters[0].x')-coastX-450*(run('mapClock')-coastClock))<.001);step(.15);assert(run('teamState(fighters[0]).diving')>.3);step(.5);assert.equal(run('teamState(fighters[0]).diving'),0);assert.equal(run('fighters[0].dodge'),0);
setupTeam();run('switchAthlete(fighters[0]);touchMove.x=0;touchMove.y=1;attack(0,1)');step(.1);const touchDiveY=run('fighters[0].y');run('touchMove.x=-1;touchMove.y=0');step(.1);assert.equal(run('fighters[0].dx'),-1);assert(Math.abs(run('fighters[0].y')-touchDiveY)<.001);run('touchMove.x=touchMove.y=0');
console.log('PASS: Dive starts in movement direction, keyboard/touch steering during dive, heading retained on release, and longer/slower 0.8s/450 Dive with correct expiry.');
function setupSelfish(card){setupTeam();sandbox.soloCard=card;run('loadouts[0]=[soloCard];spawnRound();useTestMap();fighters[0].x=100;fighters[0].y=350;fighters[1].x=170;fighters[1].y=350')}
const selfishRng=Math.random;setupTeam();Math.random=()=>0;run('fighters[0].hp=0;endRound()');assert(run("cardDraft.options.includes('selfish')"));run("selectAbilityCard('selfish')");assert.equal(run('cardDraft.phase'),'selfish');assert.equal(run('loadouts[0].length'),0);assert.equal(run('cardDraft.options.length'),3);run("selectAbilityCard('selfish_swimmer')");step(2.3);assert.equal(run('selfishAthlete(fighters[0])'),1);assert.equal(run('fighters[0].hp'),120);assert.equal(run('teamState(fighters[0]).members.map(m=>m.hp).join()'),'0,120,0');assert.equal(run('getMoves(fighters[0])[2][0]'),'Pool');assert.equal(run('validAthletics(fighters[0])'),true);Math.random=selfishRng;
setupSelfish('selfish_swimmer');run('attack(0,2)');assert.equal(run('zones.filter(z=>z.kind==="pool").length'),1);assert.equal(run('terrainAt(fighters[0]).water'),true);assert.equal(run('terrainAt(fighters[1]).water'),true);assert.equal(run('terrainSpeed(fighters[0])'),1);assert.equal(run('terrainSpeed(fighters[1])'),.55);run('teamState(fighters[0]).switchCd=0;syncTeam(fighters[0]);fighters[0].anim=0;attack(0,2)');assert.equal(run('zones.filter(z=>z.kind==="pool").length'),1);run('spawnRound();useTestMap()');assert.equal(run('teamState(fighters[0]).poolUsed'),false);assert.equal(run('zones.length'),0);
setupSelfish('selfish_runner');run('sportsHistory.set(fighters[0],[runnerSnapshot(fighters[0],0)]);keys.add("d")');step(.5);run('keys.clear()');step(.5);run('applyDamage(fighters[0],40);addBleed(fighters[0],5)');step(1.1);run('teamState(fighters[0]).members[0].cd[0]=5;syncTeam(fighters[0]);attack(0,2)');assert.equal(run('fighters[0].hp'),120);assert.equal(run('fighters[0].athletics.bleed'),0);assert(run('fighters[0].x<150'));assert.equal(run('fighters[0].cd[0]'),5);assert.equal(run('fighters[0].cd[2]'),20);assert.equal(run('fighters[1].hp'),140);
setupSelfish('selfish_skater');run('attack(0,2)');step(.1);assert.equal(run('fighters[1].athletics.bleed'),1);assert.equal(run('fighters[1].hp'),138);
setupSelfish('selfish_skater');run('zone(0,100,350,200,0,0,"ice",8);attack(0,2)');step(.75);assert.equal(run('fighters[1].athletics.bleed'),3);assert.equal(run('fighters[1].hp'),134);run('applyDamage(fighters[0],1000)');assert.equal(run('fighters[0].hp'),0);assert.equal(run('teamState(fighters[0]).active'),2);
assert.equal(run("validLoadout(4,['selfish_runner','selfish_swimmer'])"),false);assert.equal(run("validLoadout(0,['selfish_runner'])"),false);assert.equal(run("validLoadout(4,['selfish_runner','vitality'])"),true);
console.log('PASS: two-stage Selfish selection, locked solo athlete/120 HP, Pool once per round/water/reset, two-second own-state rewind without cooldown/enemy rewind, one/three Spin Bleed pulses, final solo death and loadout validation.');
